import json, re
from pathlib import Path
for path in sorted(Path('world/pages').glob('missions-*.json')):
    data = json.loads(path.read_text())
    def records(value):
        if isinstance(value, dict):
            if 'mission_id' in value and 'status' in value:
                yield value
            else:
                for nested in value.values():
                    yield from records(nested)
        elif isinstance(value, list):
            for nested in value:
                yield from records(nested)
    for record in records(data):
        text = record['mission_id'] + ' ' + record.get('goal', '')
        if re.search(r'price-update-review|CATALOGUE-CONSOLIDATED-RELEASE-CANDIDATE|catalogue price update|price-update review', text, re.I):
            print(json.dumps({key: record.get(key) for key in ('mission_id', 'status', 'agent_id', 'evidence')}, ensure_ascii=False))
print(json.dumps({'mission_pages_read': len(list(Path('world/pages').glob('missions-*.json')))}))
